export const relatedGuides=(item,available)=>{
 const paths=relatedGuidePaths[item.path.split('/').filter(Boolean).at(-1)];
 if(!paths)throw Error(`Missing related guides for ${item.path}`);
 return paths.map(slug=>available.find(page=>page.path===`/guides/${slug}/`)).filter(Boolean);
};
export function journalArticle(item,offers,available){const sections=journalSections(item.path,offers).map(section=>({...section,body:contextualizeGuideBody(section.body,item.path)}));const nextLinks=(contextualGuideLinks[item.path]||[]).filter(([target])=>!target.startsWith('/guides/')||available.some(g=>g.path===target));if(nextLinks.length)sections.push({id:'next-decision',title:'Choose your next step',body:'<ul>'+nextLinks.map(([target,label])=>'<li><a href="'+target+'">'+label+'</a></li>').join('')+'</ul>'});return `<article class="journal-article"><header class="journal-header"><p class="eyebrow">${item.category} / ${item.minutes} min read</p><h1>${e(item.title)}</h1><p class="lede">${e(item.description)}</p><p class="journal-byline">By <a href="/about/">Wonder and Method</a> · Published <time datetime="${item.datePublished}">${readableDate(item.datePublished)}</time>${item.dateModified!==item.datePublished?` · Updated <time datetime="${item.dateModified}">${readableDate(item.dateModified)}</time>`:''}</p>${guideAction(item)}</header><div class="journal-layout"><nav class="journal-toc" aria-label="In this guide"><p class="eyebrow">In this guide</p><ol>${sections.map(x=>`<li><a href="#${x.id}">${e(x.title.replace(/^\d+[.)]\s*/,''))}</a></li>`).join('')}</ol></nav><div class="journal-prose">${guideDecision(item.path,offers)}${articleFigure(item)}${sections.map(x=>`<section id="${x.id}"><h2>${e(x.title)}</h2>${['owned','owned-change'].includes(x.id)?`<details class="journal-example"><summary>Read the dated studio example and its limits</summary><div>${x.body}</div></details>`:x.body}</section>`).join('')}${guideAction(item)}<p class="journal-editorial-contact"><a href="/contact/?request_kind=question#inquiry">Send the studio a correction or question</a></p></div></div></article><section class="journal-related"><p class="eyebrow">Keep exploring</p><h2>Related guides</h2><div class="journal-grid">${relatedGuides(item,available).map(item=>journalCard(item)).join('')}</div><a class="text-link" href="/guides/">All guides</a></section>`;}
